import json
from itertools import permutations

def solve():
    houses = [1, 2, 3]

    names = ["Peter", "Arnold", "Eric"]
    car_models = ["toyota camry", "ford f150", "tesla model 3"]
    house_styles = ["ranch", "colonial", "victorian"]
    pets = ["cat", "dog", "fish"]
    occupations = ["engineer", "doctor", "teacher"]
    vacations = ["city", "mountain", "beach"]

    solution = None

    for cars in permutations(car_models):
        # 2. The person who owns a Toyota Camry is in the second house.
        if cars[1] != "toyota camry":
            continue

        for styles in permutations(house_styles):
            # 6. The person who owns a Toyota Camry is directly left of the person living in a colonial-style house.
            camry_idx = cars.index("toyota camry")
            if camry_idx + 1 >= len(houses):
                continue
            if styles[camry_idx + 1] != "colonial":
                continue

            for pet_list in permutations(pets):
                # 1. The person with an aquarium of fish is in the first house.
                if pet_list[0] != "fish":
                    continue

                for name_list in permutations(names):
                    # 5. The person in a ranch-style home is somewhere to the left of Peter.
                    if not (styles.index("ranch") < name_list.index("Peter")):
                        continue
                    # 7. Arnold is the person who has a cat.
                    if pet_list[name_list.index("Arnold")] != "cat":
                        continue

                    for vac_list in permutations(vacations):
                        # 3. The person who enjoys mountain retreats is not in the second house.
                        if vac_list[1] == "mountain":
                            continue
                        # 4. The person who prefers city breaks is not in the second house.
                        if vac_list[1] == "city":
                            continue
                        # 8. Eric is somewhere to the left of the person who enjoys mountain retreats.
                        if not (name_list.index("Eric") < vac_list.index("mountain")):
                            continue

                        for jobs in permutations(occupations):
                            # 9. The person who is an engineer is not in the third house.
                            if jobs[2] == "engineer":
                                continue
                            # 11. The person who owns a dog is the person who is an engineer.
                            if jobs[pet_list.index("dog")] != "engineer":
                                continue
                            # 10. The person who owns a Tesla Model 3 is somewhere to the left of the person who is a teacher.
                            if not (cars.index("tesla model 3") < jobs.index("teacher")):
                                continue

                            # All constraints satisfied
                            solution = []
                            for i in range(3):
                                solution.append({
                                    "House": str(houses[i]),
                                    "Name": name_list[i],
                                    "CarModel": cars[i],
                                    "HouseStyle": styles[i],
                                    "Pet": pet_list[i],
                                    "Occupation": jobs[i],
                                    "Vacation": vac_list[i],
                                })
                            # Found the unique solution
                            result = {
                                "solution": {
                                    "header": ["House", "Name", "CarModel", "HouseStyle", "Pet", "Occupation", "Vacation"],
                                    "rows": [
                                        [row["House"], row["Name"], row["CarModel"], row["HouseStyle"], row["Pet"], row["Occupation"], row["Vacation"]]
                                        for row in sorted(solution, key=lambda x: int(x["House"]))
                                    ]
                                }
                            }
                            print(json.dumps(result))
                            return

if __name__ == "__main__":
    solve()
